using Contoso.Services;

[TestClass]
public sealed class ServiceRegistryTests
{
    private readonly ServiceRegistry _registry;

    public ServiceRegistryTests()
    {
        _registry = new ServiceRegistry();
    }

    [TestMethod]
    public void Resolve_RegisteredService_ReturnsSameInstance()
    {
        var service = new FakeLogger();

        _registry.Register<ILogger>(service);
        var resolved = _registry.Resolve<ILogger>();

        Assert.AreSame(service, resolved);
    }

    [TestMethod]
    public void Resolve_UnregisteredService_ReturnsNull()
    {
        var resolved = _registry.Resolve<ILogger>();

        Assert.IsNull(resolved);
    }

    [TestMethod]
    public void GetAll_ContainsRegisteredService()
    {
        var service = new FakeLogger();

        _registry.Register<ILogger>(service);

        Assert.Contains(service, _registry.GetAll());
    }

    [TestMethod]
    public void GetAll_DoesNotContainRemovedService()
    {
        var service = new FakeLogger();
        _registry.Register<ILogger>(service);

        _registry.Remove<ILogger>();

        Assert.DoesNotContain(service, _registry.GetAll());
    }

    [TestMethod]
    public void GetAll_BeforeRegistration_IsEmpty()
    {
        Assert.IsEmpty(_registry.GetAll());
    }

    [TestMethod]
    public void GetAll_AfterRegistration_IsNotEmpty()
    {
        _registry.Register<ILogger>(new FakeLogger());

        Assert.IsNotEmpty(_registry.GetAll());
    }

    private interface ILogger;
    private sealed class FakeLogger : ILogger;
}

